#!/usr/bin/env python3
"""Read TempleOS screen text from a screendump PNG (exact 8x8 glyph match).

TempleOS draws all text with the fixed kernel font (sys_font_std,
Kernel/FontStd.HC) on an 80x60 cell grid, so glyphs can be matched exactly
-- no fuzzy OCR. Cells that are not two-color text (graphics) print as
middle dot characters.

Usage:
  scrtext.py FILE.png                 print the 80x60 screen text
  scrtext.py FILE.png --grep STRING   exit 0 if STRING appears (case-insens.)
"""
import subprocess
import sys

FONT_HEX = ""
W, H = 640, 480

def glyph_table():
    tab = {}
    for i in range(256):
        v = int(FONT_HEX[i * 16:(i + 1) * 16], 16)
        if 32 <= i < 127:
            tab.setdefault(v, chr(i))
    return tab

def cells(raw):
    tab = glyph_table()
    out = []
    for cy in range(H // 8):
        line = []
        for cx in range(W // 8):
            colors = {}
            px = []
            for y in range(8):
                off = ((cy * 8 + y) * W + cx * 8) * 3
                row = []
                for x in range(8):
                    c = raw[off + x * 3:off + x * 3 + 3]
                    colors[c] = colors.get(c, 0) + 1
                    row.append(c)
                px.append(row)
            if len(colors) == 1:
                line.append(" ")
                continue
            if len(colors) != 2:
                line.append("\u00b7")
                continue
            # try both fg/bg assignments
            (c1, _), (c2, _) = sorted(colors.items(), key=lambda kv: -kv[1])
            hit = "\u00b7"
            for fg in (c2, c1):
                bits = 0
                for y in range(8):
                    for x in range(8):
                        if px[y][x] == fg:
                            bits |= 1 << (y * 8 + x)
                ch = tab.get(bits)
                if ch:
                    hit = ch
                    break
            line.append(hit)
        out.append("".join(line).rstrip())
    return out

def main():
    path = sys.argv[1]
    raw = subprocess.check_output(
        ["ffmpeg", "-v", "quiet", "-i", path, "-f", "rawvideo",
         "-pix_fmt", "rgb24", "-s", f"{W}x{H}", "-"])
    lines = cells(raw)
    if len(sys.argv) > 3 and sys.argv[2] == "--grep":
        needle = sys.argv[3].lower()
        text = "\n".join(lines).lower()
        sys.exit(0 if needle in text else 1)
    print("\n".join(lines))

if __name__ == "__main__":
    main()
